-- Content pack 11: ONE rule for the articles. Merges 6 rules into "a-or-the" ("Articles: the, a / an or no article").
-- GENERATED by scripts/merge-article-rules.mjs from database/rules-import/article-merge.json. Do not edit by hand.
--
-- What it does:
--   1. Writes down, on each merged rule, which examples and exercises it had (metadata.example_ids / exercise_ids), so it can be undone.
--   2. Gives "a-or-the" the new title and explanation (the / no article come first, jobs are included).
--   3. Adds 23 new examples and 35 new exercises (mostly the / no article, jobs).
--   4. Moves the examples, exercises, word links, mistake links, practice attempts, notes and progress of the merged rules to "a-or-the"
--      (progress and notes only where the learner has none on "a-or-the" yet).
--   5. Deletes repeated examples (same type and text) and repeated exercises (same prompt) inside "a-or-the".
--   6. Sets is_active = false on the merged rules: the-one-of-a-kind, no-article-in-general, no-article-names-meals-languages, the-geography, no-article-routine-places, a-with-jobs-and-quantities. They are NOT deleted.
-- Safe to run more than once. Run it in the Supabase SQL Editor (project "SpellSprint").
-- HOW TO UNDO: run database/content-pack-11-undo.sql (moves the examples and exercises back and switches the rules on; the
-- deleted exact duplicates and the new rows stay, the old explanation of "a-or-the" is put back).

begin;

update public.rules r
set metadata = r.metadata || jsonb_build_object(
  'merged_into', 'a-or-the',
  'was_active', r.is_active,
  'example_ids', (select coalesce(jsonb_agg(e.id), '[]'::jsonb) from public.rule_examples e where e.rule_id = r.id),
  'exercise_ids', (select coalesce(jsonb_agg(x.id), '[]'::jsonb) from public.rule_exercises x where x.rule_id = r.id)
)
where r.slug in ('the-one-of-a-kind', 'no-article-in-general', 'no-article-names-meals-languages', 'the-geography', 'no-article-routine-places', 'a-with-jobs-and-quantities') and not (r.metadata ? 'merged_into');

update public.rules
set title = 'Articles: the, a / an or no article',
    short_explanation = 'Ask: do we both know which one? Yes, or there is only one (the sun, the best, the Thames, the manager of this shop): the. No, just one of many, or what someone is (She is a nurse; twice a week): a / an. In general, or a name, language, sport, meal, routine place or title (I like music; Doctor Brown; go to school; by bus): no article.',
    tts_text = 'Use the when we both know which one. Use a or an for any one, or for a job. Use no article for things in general, names, languages, meals and routine places.',
    mnemonic = 'Known or only one: the. Any one, or a job: a. In general, names, titles: nothing.',
    updated_at = now()
where slug = 'a-or-the';

