update public.rule_examples set rule_id = (select id from public.rules where slug = 'a-or-the') where rule_id in (select id from public.rules where slug in ('the-one-of-a-kind', 'no-article-in-general', 'no-article-names-meals-languages', 'the-geography', 'no-article-routine-places', 'a-with-jobs-and-quantities'));
update public.rule_exercises set rule_id = (select id from public.rules where slug = 'a-or-the') where rule_id in (select id from public.rules where slug in ('the-one-of-a-kind', 'no-article-in-general', 'no-article-names-meals-languages', 'the-geography', 'no-article-routine-places', 'a-with-jobs-and-quantities'));
update public.mistake_rule_links set rule_id = (select id from public.rules where slug = 'a-or-the') where rule_id in (select id from public.rules where slug in ('the-one-of-a-kind', 'no-article-in-general', 'no-article-names-meals-languages', 'the-geography', 'no-article-routine-places', 'a-with-jobs-and-quantities'));
update public.rule_practice_attempts set rule_id = (select id from public.rules where slug = 'a-or-the') where rule_id in (select id from public.rules where slug in ('the-one-of-a-kind', 'no-article-in-general', 'no-article-names-meals-languages', 'the-geography', 'no-article-routine-places', 'a-with-jobs-and-quantities'));

update public.rule_word_links l set rule_id = (select id from public.rules where slug = 'a-or-the')
where l.rule_id in (select id from public.rules where slug in ('the-one-of-a-kind', 'no-article-in-general', 'no-article-names-meals-languages', 'the-geography', 'no-article-routine-places', 'a-with-jobs-and-quantities'))
  and not exists (select 1 from public.rule_word_links o where o.rule_id = (select id from public.rules where slug = 'a-or-the') and o.word_id = l.word_id);

update public.user_rule_progress p set rule_id = (select id from public.rules where slug = 'a-or-the')
where p.rule_id in (select id from public.rules where slug in ('the-one-of-a-kind', 'no-article-in-general', 'no-article-names-meals-languages', 'the-geography', 'no-article-routine-places', 'a-with-jobs-and-quantities'))
  and not exists (select 1 from public.user_rule_progress o where o.rule_id = (select id from public.rules where slug = 'a-or-the') and o.user_id = p.user_id);

update public.user_rule_notes n set rule_id = (select id from public.rules where slug = 'a-or-the')
where n.rule_id in (select id from public.rules where slug in ('the-one-of-a-kind', 'no-article-in-general', 'no-article-names-meals-languages', 'the-geography', 'no-article-routine-places', 'a-with-jobs-and-quantities'))
  and not exists (select 1 from public.user_rule_notes o where o.rule_id = (select id from public.rules where slug = 'a-or-the') and o.user_id = n.user_id);

delete from public.rule_examples a using public.rule_examples b
where a.rule_id = (select id from public.rules where slug = 'a-or-the') and b.rule_id = a.rule_id
  and a.example_type = b.example_type and a.text = b.text and a.ctid > b.ctid;

delete from public.rule_exercises a using public.rule_exercises b
where a.rule_id = (select id from public.rules where slug = 'a-or-the') and b.rule_id = a.rule_id
  and a.prompt = b.prompt and a.ctid > b.ctid;

update public.rules set is_active = false, updated_at = now() where slug in ('the-one-of-a-kind', 'no-article-in-general', 'no-article-names-meals-languages', 'the-geography', 'no-article-routine-places', 'a-with-jobs-and-quantities');

